# Generate a graph with 10 vertices and 25 edges (between 21 and 30)
edges = []
count = 0
for u in range(10):
    for v in range(u+1, 10):
        if count < 25:
            edges.append((u, v))
            count += 1
        else:
            break
    if count >= 25:
        break

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Verify all edges satisfy 0 <= u < v < 10
for u, v in edges:
    assert 0 <= u < v < 10, f"Invalid edge: ({u}, {v})"

print("All edges are valid!")
